mapper.select:
SELECT 
FROM SF_RESOURCE_STOCK S
JOIN SF_DEPARTMENT D ON D.DEPARTMENT_ID = S.DEPARTMENT_ID
JOIN SF_RESOURCE_ITEM I ON I.ITEM_ID = S.ITEM_ID


        S.STATUS = 'ACTIVE'


        AND S.DEPARTMENT_ID = #{departmentId}


        AND S.ITEM_ID = #{itemId}


        AND I.CATEGORY = #{category}


ORDER BY S.DEPARTMENT_ID, S.ITEM_ID

SELECT * FROM (
    SELECT a.*, ROWNUM AS RN FROM (
        SELECT 


        ORDER BY S.DEPARTMENT_ID, S.ITEM_ID
    ) a
    WHERE ROWNUM <= #{endRow}
)
WHERE RN > #{startRow}

SELECT ITEM_ID, NAME, CATEGORY, UNIT, RETURNABLE, DESCRIPTION, CREATED_AT
FROM SF_RESOURCE_ITEM
WHERE ITEM_ID = #{itemId}

SELECT LOG_ID, ITEM_ID, FIELD_NAME, OLD_VALUE, NEW_VALUE, CHANGED_BY, CHANGED_BY_NAME, CHANGED_AT
FROM (
    SELECT L.LOG_ID, L.ITEM_ID, L.FIELD_NAME, L.OLD_VALUE, L.NEW_VALUE,
           L.CHANGED_BY, M.NAME AS CHANGED_BY_NAME, L.CHANGED_AT
    FROM SF_RESOURCE_ITEM_LOG L
    JOIN SF_MEMBER M ON M.MEMBER_ID = L.CHANGED_BY
    WHERE L.ITEM_ID = #{itemId}
    ORDER BY L.LOG_ID DESC
)
WHERE ROWNUM <= #{limit}
